-- | ACVP test vectors for ML-DSA, from NIST's ACVP-Server.
--
-- Generated from gen-val/json-files/ML-DSA-{keyGen,sigGen}-FIPS204.  The
-- signature vectors are the pure, external-interface groups, which is what
-- this module implements.
--
-- Every combination -- deterministic or hedged, with a context string or
-- without -- is taken at ML-DSA-44, which is the smallest, and the ones with
-- a context at the other two.  That exercises each path through the Haskell
-- at 44 and would still catch a size constant that is wrong at 65 or 87,
-- without carrying four times the vectors for it.
--
-- They are here rather than downloaded when the suite runs, so that it needs
-- no network and a release tarball carries what it was tested against.
module PubKey.MLDSAVectors (
    KeyGenVector (..),
    SigGenVector (..),
    ExtMuVector (..),
    keyGenVectors,
    sigGenVectors,
    extMuVectors,
) where

-- | A seed in, the key pair out.
data KeyGenVector = KeyGenVector
    { kgSet :: String
    , kgId :: Int
    , kgSeed :: String
    , kgPk :: String
    , kgSk :: String
    }

-- | A signing key, a message and a context in, the signature out.  When
-- 'sgDeterministic' the randomness is zeroes and 'sgRnd' is empty; otherwise
-- 'sgRnd' is the randomness the vector was produced with.
data SigGenVector = SigGenVector
    { sgSet :: String
    , sgId :: Int
    , sgDeterministic :: Bool
    , sgSk :: String
    , sgMessage :: String
    , sgContext :: String
    , sgRnd :: String
    , sgSignature :: String
    }

